import os,time,json,pathlib,subprocess,signal,tempfile
base=pathlib.Path(tempfile.gettempdir());start=pathlib.Path('/tmp/history-integration-before.json').stat().st_mtime
result={'samples':0,'peak_new_work_bytes':0,'minimum_free_bytes':None,'scope':'Combined newly created history-integration and job-history-bounded directories, excluding prior retained candidates; sampled each second.'}
prior=pathlib.Path('/tmp/history-integration-combined-disk.json')
if prior.exists(): result.update(json.loads(prior.read_text()))
result['scope'] = 'Combined new temporary work plus durable review candidate and control; prior retained candidates excluded. One-second samples with brief monitor restart gaps.'
while True:
 rows={}
 for line in subprocess.check_output(['ps','-axo','pid,ppid,command'],text=True).splitlines()[1:]:
  p,pp,cmd=line.strip().split(None,2);rows[int(p)]=(int(pp),cmd)
 roots={p for p,(_,cmd) in rows.items() if any(n in cmd for n in ['src/scripts/test-job-history-integration-full.js','/tmp/history-integration-prefix-test.py','/tmp/history-integration-remaining-test.py','/tmp/history-integration-recovery-test.py','node --max-old-space-size=128 /tmp/history-integration-gc-probe.cjs'])}
 if not roots:break
 total=0
 for directory in [*base.iterdir(),pathlib.Path('/Users/adampugh/GitHub/public-job-feed/data/jobs/history-migrations/20261019-writer-review')]:
  try:
   if not (directory.name.startswith(('history-integration-','job-history-bounded-')) or directory.name=='20261019-writer-review') or not directory.is_dir() or directory.stat().st_birthtime<start:continue
   for folder,dirs,files in os.walk(directory):
    for name in files:
     try:
      s=(pathlib.Path(folder)/name).lstat();total+=max(s.st_size,s.st_blocks*512)
     except FileNotFoundError:pass
  except FileNotFoundError:pass
 s=os.statvfs(base);free=s.f_bavail*s.f_frsize;result['samples']+=1;result['peak_new_work_bytes']=max(result['peak_new_work_bytes'],total);result['minimum_free_bytes']=min(result['minimum_free_bytes'] or free,free)
 if total>16*1024**3 or free<32*1024**3:
  selected=set(roots)
  while True:
   more={p for p,(pp,_) in rows.items() if pp in selected}-selected
   if not more:break
   selected|=more
  result['error']='Combined work exceeded the unchanged disk gate'
  for p in sorted(selected,reverse=True):
   try:os.kill(p,signal.SIGTERM)
   except ProcessLookupError:pass
 pathlib.Path('/tmp/history-integration-combined-disk.json').write_text(json.dumps(result,indent=2))
 if result.get('error'):break
 time.sleep(1)
print(json.dumps(result))
